function statusAfterAccountDelete(){const status=document.querySelector('#cloud-status'),bank=document.querySelector('#bank-status');if(status)status.textContent='Account and cloud data deleted. Local device data remains. Sign in again only if you want to create a new account.';if(bank)bank.textContent='No bank link is associated with the deleted account.';for(const id of ['cloud-push','cloud-pull','cloud-signout','cloud-delete','cloud-delete-account','mono-connect','mono-import','mono-disconnect']){const button=document.querySelector(`#${id}`);if(button)button.disabled=true}}
async function updateCloudStatus(){const status=document.querySelector('#cloud-status'),bank=document.querySelector('#bank-status');if(!status||!bank)return;const cfg=cloudSettings(),ids=['cloud-push','cloud-pull','cloud-signout','cloud-delete','cloud-delete-account','mono-connect','mono-import','mono-disconnect'];for(const id of ids){const button=document.querySelector(`#${id}`);if(button)button.disabled=!cfg}if(!cfg){status.textContent='Cloud sync is not configured. Save your Supabase project URL and publishable key to begin.';bank.textContent='Configure cloud sync first. Bank linking is disabled until the site owner enables it.';document.querySelector('#cloud-delete-account').disabled=true;return}try{const user=await cloudUser();if(!user){status.textContent='Cloud is configured. Enter your email to sign in.';bank.textContent='Sign in before linking an account.';document.querySelector('#cloud-delete-account').disabled=true;return}status.textContent=`Signed in as ${user.email||'your account'}. Use “Save a cloud copy” or “Load cloud copy” when you choose.`;document.querySelector('#cloud-delete-account').disabled=false;try{if(!await monoAvailable()){bank.textContent='Bank linking is not enabled for this site yet. The owner must complete Mono setup and privacy review first.';for(const id of ['mono-connect','mono-import','mono-disconnect'])document.querySelector(`#${id}`).disabled=true;return}const link=await monoStatus();if(link?.mono_account_id){bank.textContent=`Bank linked${link.institution?` · ${link.institution}`:''} · ${link.status}. Import transactions when ready.`;document.querySelector('#mono-connect').disabled=true;document.querySelector('#mono-import').disabled=false;document.querySelector('#mono-disconnect').disabled=false}else{bank.textContent='No bank linked. Connect a bank to request transaction access through Mono.';document.querySelector('#mono-connect').disabled=false;document.querySelector('#mono-import').disabled=true;document.querySelector('#mono-disconnect').disabled=true}}catch(error){bank.textContent=`Bank-link service is not ready yet. Deploy the Supabase setup in the source folder. ${error.message||''}`;document.querySelector('#mono-connect').disabled=true;document.querySelector('#mono-import').disabled=true;document.querySelector('#mono-disconnect').disabled=true}}catch(error){status.textContent=`Cloud setup needs attention: ${error.message||'could not connect.'}`;bank.textContent='Bank linking requires cloud sign-in and server setup.'}}
function renderExpenses(){if(!plan)plan=initialPlan(salary);const spend=Object.entries(plan).filter(([id])=>!['savings','emergency'].includes(id)).reduce((a,[,n])=>a+n,0),saved=plan.savings+(plan.emergency||0),remaining=salary-spend-saved,totalPaid=Object.values(paidAmounts).reduce((sum,n)=>sum+n,0),priorityLabels={protect:'PROTECT FIRST',important:'KEEP IF POSSIBLE',reduce:'CAN REDUCE'};app.innerHTML=`<section class="screen-wrap"><div class="screen-head"><div><div class="eyebrow">02 / SET YOUR PRIORITIES</div><h2>Give your money a plan.</h2><p>Choose what matters most. Your priority labels stay with your saved month.</p></div></div><div class="paid-note"><b>Already paid for something?</b> Enter the amount paid under that expense. It is included in your plan totals and reduces the remaining amount for that category.</div><div class="expenses-layout"><div class="expense-list">${EXPENSES.map(x=>{const max=Math.max(10000,Math.round(salary*x.max/1000)*1000),paid=paidAmounts[x.id]||0;return `<div class="expense-item"><div class="expense-title"><span>${x.icon} &nbsp;${x.name}</span><small>${x.mandatory?'ESSENTIAL':'FLEXIBLE'}</small></div><label class="priority-field"><span>How important is this?</span><select data-priority="${x.id}" aria-label="Priority for ${x.name}">${Object.entries(priorityLabels).map(([value,label])=>`<option value="${value}" ${priorities[x.id]===value?'selected':''}>${label}</option>`).join('')}</select></label><input class="expense-slider" data-exp="${x.id}" type="range" min="0" max="${max}" step="1000" value="${Math.min(max,plan[x.id])}" aria-label="Adjust ${x.name} budget slider"><label class="expense-amount-field"><span>Planned amount (₦)</span><input data-exp="${x.id}" type="number" min="0" max="${max}" step="1" inputmode="numeric" placeholder="e.g. 12345" value="${plan[x.id]}" aria-label="Enter exact ${x.name} budget in naira"></label><label class="expense-paid-field"><span>Paid so far (₦)</span><input data-paid="${x.id}" type="number" min="0" max="${plan[x.id]}" step="1" inputmode="numeric" placeholder="0" value="${paid||''}" aria-label="Enter amount already paid for ${x.name} in naira"></label><small class="expense-balance">${formatNaira(Math.max(0,plan[x.id]-paid))} remaining in this category</small></div>`}).join('')}</div><aside class="expense-card"><h3>Your month, your call.</h3><p>Monthly essentials and optional costs are committed now. Keep a little breathing room for the surprises waiting in the game.</p><div class="expense-total">${formatNaira(remaining)}</div><div class="expense-meta"><span>Salary</span><b>${formatNaira(salary)}</b></div><div class="expense-meta"><span>Planned spend</span><b>${formatNaira(spend)}</b></div><div class="expense-meta"><span>Already paid</span><b>${formatNaira(totalPaid)}</b></div><div class="expense-meta"><span>Put aside</span><b>${formatNaira(saved)}</b></div><div class="expense-meta"><span>Available buffer</span><b>${formatNaira(remaining)}</b></div><button class="primary" id="begin" ${remaining<0?'disabled':''}>LET THE MONTH BEGIN →</button></aside></div><div class="button-row"><button class="text-link" id="budget-back">← Salary</button><span class="field-help">Tip: enter an exact amount or use the slider. A buffer makes curveballs easier to handle.</span></div></section>`;
 app.querySelectorAll('[data-exp]').forEach(inp=>{const update=()=>{const id=inp.dataset.exp;const max=Math.max(10000,Math.round(salary*EXPENSES.find(x=>x.id===id).max/1000)*1000);plan[id]=Math.min(max,Math.max(0,Math.round(Number(inp.value)||0)));paidAmounts[id]=Math.min(paidAmounts[id]||0,plan[id]);saveExpenseDraft()};inp.oninput=update;inp.onchange=()=>{update();renderExpenses()}});app.querySelectorAll('[data-paid]').forEach(inp=>{const update=()=>{const id=inp.dataset.paid;paidAmounts[id]=Math.min(Number(plan[id])||0,Math.max(0,Math.round(Number(inp.value)||0)));saveExpenseDraft()};inp.oninput=update;inp.onchange=()=>{update();renderExpenses()}});app.querySelectorAll('[data-priority]').forEach(select=>select.onchange=()=>{priorities[select.dataset.priority]=select.value;saveExpenseDraft()});document.querySelector('#budget-back').onclick=()=>{screen='salary';render()};document.querySelector('#begin').onclick=()=>{saveExpenseDraft();screen='review';render()};}
function renderBudgetReview(){if(!plan)plan=initialPlan(salary);const spend=Object.entries(plan).filter(([id])=>!['savings','emergency'].includes(id)).reduce((sum,[,amount])=>sum+Number(amount||0),0),saved=Number(plan.savings||0)+Number(plan.emergency||0),planned=spend+saved,buffer=salary-planned,totalPaid=Object.values(paidAmounts).reduce((sum,n)=>sum+n,0),advice=[];if(buffer<0)advice.push(`Your plan is ${formatNaira(Math.abs(buffer))} over your salary. Reduce one or more amounts before starting.`);else if(buffer<salary*.05)advice.push(`Your buffer is ${formatNaira(buffer)} (${Math.floor(buffer/salary*100)}% of income). Consider leaving more for unexpected costs.`);else advice.push(`You have a ${formatNaira(buffer)} buffer after these planned amounts.`);if(totalPaid)advice.push(`${formatNaira(totalPaid)} is already paid. This counts toward the category budgets above; the remaining planned amount is ${formatNaira(Math.max(0,planned-totalPaid))}.`);for(const [id,label] of [['food','Food and groceries'],['rent','Rent and housing'],['transport','Transportation']])if(!Number(plan[id]))advice.push(`No amount is set for ${label}. Check whether you need to add one.`);if(!saved)advice.push('Nothing is set aside for savings or emergencies. Add an amount if that is a priority for you.');app.innerHTML=`<section class="screen-wrap budget-review"><div class="screen-head"><div><div class="eyebrow">03 / QUICK CHECK BEFORE YOU START</div><h2>Review your month</h2><p>Check the numbers and adjust anything that does not look right.</p></div></div><div class="review-advice-card"><div class="review-advice-heading"><span aria-hidden="true">✳</span><div><b>A quick look at your plan</b><small>These checks use only the amounts you entered. You can change them at any time before the month begins.</small></div></div><ul>${advice.map(item=>`<li>${e(item)}</li>`).join('')}</ul></div><div class="review-totals"><div><span>Monthly salary</span><b>${formatNaira(salary)}</b></div><div><span>Planned expenses</span><b>${formatNaira(spend)}</b></div><div><span>Paid so far</span><b>${formatNaira(totalPaid)}</b></div><div><span>Savings & emergency fund</span><b>${formatNaira(saved)}</b></div><div class="${buffer<0?'review-negative':''}"><span>Left as buffer</span><b>${buffer<0?`−${formatNaira(Math.abs(buffer))}`:formatNaira(buffer)}</b></div></div><div class="review-actions"><button class="secondary" id="review-adjust">← REVIEW OR CHANGE AMOUNTS</button><button class="primary" id="review-begin" ${buffer<0?'disabled':''}>${buffer<0?'REDUCE YOUR PLAN TO CONTINUE':'BEGIN THE MONTH →'}</button></div></section>`;document.querySelector('#review-adjust').onclick=()=>{screen='expenses';render()};const begin=document.querySelector('#review-begin');if(begin)begin.onclick=()=>{state=createGame(salary,plan,salaryMeta,priorities);sessionStorage.removeItem(EXPENSE_DRAFT_KEY);shownEvent=null;screen='game';persist();render()};}
function stat(label,value,kind=''){return `<div class="stat-row"><div class="stat-head"><span>${label}</span><span>${value}%</span></div><div class="stat-track"><div class="stat-fill ${kind}" style="width:${value}%"></div></div></div>`}
function renderGame(){const event=state.currentEvent;const spent=state.totalSpent;app.innerHTML=`<section class="screen-wrap"><div class="game-layout"><div class="game-main"><div class="day-ribbon"><div class="day-number">DAY ${String(state.currentDay).padStart(2,'0')} <span>/ 30</span></div><div class="days-progress"><div class="progress-label"><span>THE MONTH</span><span>${Math.round(state.currentDay/30*100)}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${state.currentDay/30*100}%"></div></div></div></div><div class="money-strip"><div class="money-cell"><small>💼 STARTING PAY</small><b>${formatNaira(state.salary)}</b></div><div class="money-cell primary-money"><small>💰 CASH IN HAND</small><b>${formatNaira(state.money)}</b></div><div class="money-cell"><small>📦 SPENT</small><b>${formatNaira(spent)}</b></div><div class="money-cell"><small>🌱 SAVED</small><b>${formatNaira(state.savings)}</b></div><div class="money-cell"><small>⏳ LEFT</small><b>${state.currentDay===30?'Payday!':30-state.currentDay+' days'}</b></div></div>${event?eventCard(event):state.gameStatus==='over'?'':calmCard()}${state.gameStatus==='over'?`<div class="calm-card"><div class="calm-icon">🛟</div><div><b>Emergency mode</b><p>Your finances need a reset. There’s always another payday.</p></div><button class="primary" id="see-result">SEE YOUR REPORT</button></div>`:''}</div><aside class="stats-panel"><div class="stats-title">YOUR MONTHLY VIBE</div>${stat('😊 Happiness',state.happiness)}${stat('😰 Stress',state.stress,'stress')}${stat('❤️ Health',state.health,'health')}${stat('📈 Financial stability',state.financialStability,'stability')}<div class="debt-note"><span>🧾 Debt</span><b>${formatNaira(state.debt)}</b></div></aside></div>${spendingTracker()}</section>`;
 if(event){document.querySelectorAll('[data-choice]').forEach(btn=>btn.onclick=()=>{const choice=event.choices[Number(btn.dataset.choice)];state=chooseOption(state,event,choice);if(state.gameStatus==='complete'||state.gameStatus==='over'){screen='result'}persist();render()})}else{const next=document.querySelector('#next-day');if(next)next.onclick=()=>{state=advanceDay(state);if(state.gameStatus!=='playing')screen='result';persist();render()}}const trackerForm=document.querySelector('#spending-form');if(trackerForm)trackerForm.onsubmit=event=>{event.preventDefault();const form=new FormData(trackerForm),amount=Number(form.get('amount')),category=String(form.get('category'));if(!Number.isFinite(amount)||amount<=0||!EXPENSES.some(x=>x.id===category)){notify('Enter a valid amount and category.');return}const entry={id:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`,category,amount:Math.round(amount),note:String(form.get('note')||'').trim().slice(0,80),date:new Date().toISOString()};state.spendingLog=[...state.spendingLog,entry].slice(-1000);persist();const total=state.spendingLog.filter(x=>x.category===category).reduce((sum,x)=>sum+x.amount,0),budget=state.expenses[category],name=EXPENSES.find(x=>x.id===category).name;notify(total>budget?`${name} is over budget by ${formatNaira(total-budget)}.`:budget>0&&total/budget>=.8?`${name} has used ${Math.floor(total/budget*100)}% of its budget.`:'Spending added to your tracker.');render()};document.querySelectorAll('[data-remove-spend]').forEach(button=>button.onclick=()=>{state.spendingLog=state.spendingLog.filter(x=>x.id!==button.dataset.removeSpend);persist();render()});const result=document.querySelector('#see-result');if(result)result.onclick=()=>{screen='result';persist();render()};}
function spendingTracker(){const totals=Object.fromEntries(EXPENSES.map(x=>[x.id,state.spendingLog.filter(entry=>entry.category===x.id).reduce((sum,entry)=>sum+entry.amount,0)]));const alertRows=EXPENSES.map(x=>({category:x,spent:totals[x.id],budget:state.expenses[x.id]})).filter(x=>x.spent>0&&(x.budget===0||x.spent/x.budget>=.8));const alertCopy=alertRows.length?alertRows.map(x=>x.budget===0?`${x.category.name} has spending with no budget set.`:x.spent>x.budget?`${x.category.name} is over budget by ${formatNaira(x.spent-x.budget)}.`:x.spent>=x.budget?`${x.category.name} has used its full budget.`:`${x.category.name} has used ${Math.floor(x.spent/x.budget*100)}% of its budget.`).join(' '):'No categories are close to their limit yet.';const categories=EXPENSES.map(x=>{const spent=totals[x.id],budget=state.expenses[x.id],pct=budget?Math.min(100,Math.round(spent/budget*100)):spent?100:0,over=spent>budget;return `<div class="tracked-category ${over?'is-over':''}"><div class="tracked-head"><b>${x.icon} ${e(x.name)}</b><span>${formatNaira(spent)} / ${formatNaira(budget)}</span></div><div class="tracked-bar"><span style="width:${pct}%"></span></div><small>${budget===0&&spent?'No budget set · spending is over budget':over?`Over by ${formatNaira(spent-budget)}`:spent>=budget?'Full budget used':pct>=80?'Budget alert · 80% used':`${pct}% of budget used`}</small></div>`}).join('');const recent=[...state.spendingLog].reverse().slice(0,8);return `<section class="spending-tracker"><div class="tracker-heading"><div><div class="eyebrow">YOUR REAL SPENDING · MANUAL LOG</div><h2>Are you on track?</h2><p>Log purchases to compare them with your plan. Entries stay in this browser.</p></div><div class="tracker-alert" aria-live="polite">${e(alertCopy)}</div></div><div class="tracked-categories">${categories}</div><form id="spending-form" class="spending-form"><label><span>Category</span><select name="category" aria-label="Expense category">${EXPENSES.map(x=>`<option value="${x.id}">${e(x.name)}</option>`).join('')}</select></label><label><span>Amount in naira</span><input name="amount" type="number" min="1" max="1000000000" step="1" inputmode="numeric" placeholder="e.g. 4,500" required aria-label="Spending amount in naira"></label><label class="tracker-note"><span>Note (optional)</span><input name="note" type="text" maxlength="80" placeholder="e.g. market shopping"></label><button class="primary" type="submit">ADD SPENDING</button></form>${recent.length?`<div class="recent-spending"><h3>Recent entries</h3>${recent.map(x=>`<div class="spending-entry"><div><b>${e(EXPENSES.find(category=>category.id===x.category)?.name||x.category)} · ${formatNaira(x.amount)}</b><small>${e(x.note||'Purchase')}${x.date?` · ${e(new Date(x.date).toLocaleDateString('en-NG'))}`:''}</small></div><button type="button" class="remove-spending" data-remove-spend="${e(x.id)}" aria-label="Delete spending entry: ${formatNaira(x.amount)}">Delete</button></div>`).join('')}</div>`:''}</section>`}
function eventCard(ev){const category=ev.category;return `<article class="event-card"><div class="event-label"><span class="event-dot"></span>${e(category)} &nbsp;·&nbsp; DECISION TIME</div><h2>${e(ev.title)}</h2><p>${e(ev.description)}</p><div class="choice-list">${ev.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><b>${e(c.label)}</b><span>${e(c.hint)}</span></button>`).join('')}</div></article>`}
function calmCard(){return `<div class="calm-card"><div class="calm-icon">☀️</div><div><b>A relatively calm day.</b><p>No crisis. No surprise group contribution. Enjoy the plot twist.</p></div><button class="primary" id="next-day">NEXT DAY →</button></div>`}
function renderResult(){if(!state)return;const [name,emoji]=classification(state),complete=state.gameStatus==='complete',rows=leaderboard(),myEntry=rows.some(x=>x.score===state.score&&x.salary===state.salary);app.innerHTML=`<section class="screen-wrap"><div class="report-top"><div class="report-stamp">${complete?'🎉':'🧯'}</div><h2>${complete?'MONTH COMPLETE!':'MONTH REPORT'}</h2><p>${complete?'You made it to payday. How did your month turn out?':'Your finances called an emergency meeting. Let’s see the full picture.'}</p></div><div class="result-card"><div class="result-tag">YOUR MONTHLY CLASSIFICATION</div><div class="result-name">${e(name)} ${emoji}</div><div class="score-big">${state.score.toLocaleString()}</div><div class="score-caption">SURVIVAL SCORE · Salary ${formatNaira(state.salary)}${state.salaryCurrency!=='NGN'?` · ${e(currencyAmount(state.salaryAmount,state.salaryCurrency))}`:''} · Days survived ${state.daysSurvived}/30</div><div class="report-grid"><div class="report-stat"><small>💰 Cash remaining</small><b>${formatNaira(state.money)}</b></div><div class="report-stat"><small>🌱 Savings</small><b>${formatNaira(state.savings)}</b></div><div class="report-stat"><small>😊 Happiness</small><b>${state.happiness}%</b></div><div class="report-stat"><small>😰 Stress</small><b>${state.stress}%</b></div></div></div><div class="report-details"><div class="detail-box"><h3>📊 Month at a glance</h3><div class="detail-line"><span>Salary converted to Naira</span><b>${formatNaira(state.salary)}</b></div>${state.salaryCurrency!=='NGN'?`<div class="detail-line"><span>Original salary (${e(state.salaryCurrency)})</span><b>${e(currencyAmount(state.salaryAmount,state.salaryCurrency))}</b></div><div class="detail-line"><span>Daily rate used</span><b>1 ${e(state.salaryCurrency)} = ${formatNaira(state.exchangeRate)}</b></div><div class="detail-line"><span>Rate published</span><b>${e(state.exchangeRateDate||'Unavailable')}${state.exchangeRateStale?' · saved rate':''}</b></div>`:''}<div class="detail-line"><span>Total spent</span><b>${formatNaira(state.totalSpent)}</b></div><div class="detail-line"><span>Debt remaining</span><b>${formatNaira(state.debt)}</b></div><div class="detail-line"><span>Health</span><b>${state.health}%</b></div><div class="detail-line"><span>Financial stability</span><b>${state.financialStability}%</b></div><div class="detail-line"><span>Decisions made</span><b>${(state.history||[]).length}</b></div></div><div class="detail-box"><h3>🪞 Your month, in a sentence</h3><p style="font-size:14px;line-height:1.65;color:#64736b;margin:0">${state.money===0?'Your salary entered with confidence. The month had other plans.':state.savings>state.salary*.15?'You made future-you proud, and still made room for life.':state.happiness>75?'A full life costs something. You made the memories count.':'You handled the month one decision at a time. Payday is a good look on you.'}</p><div style="margin-top:16px;color:#92a044;font-weight:800;font-size:11px">${state.eventsCompleted.length} unexpected moments handled</div></div></div>${myEntry?'':`<div class="leaderboard"><h3>🏅 Put your score on this device</h3><div class="field-help">Local leaderboard · your name and score stay in this browser.</div><div class="name-form"><input id="player-name" maxlength="16" placeholder="Your nickname" aria-label="Leaderboard nickname"><button class="primary" id="save-score">SAVE SCORE</button></div></div>`}<div class="leaderboard"><h3>🏆 Local leaderboard</h3>${rows.length?`<div class="leader-row leader-head"><span>#</span><span>PLAYER</span><span>SCORE</span><span>RESULT</span></div>${rows.map((r,i)=>`<div class="leader-row"><b>${i+1}</b><span>${e(r.name)} · ${short(r.salary)}${r.salaryCurrency&&r.salaryCurrency!=='NGN'?` (${e(currencyAmount(r.salaryAmount,r.salaryCurrency))})`:''}</span><b>${r.score.toLocaleString()}</b><span>${e(r.result)}</span></div>`).join('')}`:'<div class="field-help">No scores yet. Be the first to finish a month.</div>'}</div><div class="report-actions"><button class="primary" id="play-again">PLAY AGAIN ↻</button><button class="secondary" id="different-salary">TRY A DIFFERENT SALARY</button><button class="ghost" id="share">↗ SHARE RESULT</button></div></section>`;
 const save=document.querySelector('#save-score');if(save)save.onclick=()=>{const name=document.querySelector('#player-name').value.trim();addLeaderboard(name,state);render()};document.querySelector('#play-again').onclick=()=>{plan=initialPlan(state.salary);salary=state.salary;state=null;saveExpenseDraft();screen='expenses';render()};document.querySelector('#different-salary').onclick=()=>{state=null;screen='salary';render()};document.querySelector('#share').onclick=async()=>{const text=shareText(state);try{if(navigator.share)await navigator.share({title:'Salary Survival 🇳🇬',text});else{await navigator.clipboard.writeText(text);notify('Your result is copied and ready to share!')}}catch(err){if(err.name!=='AbortError'){try{await navigator.clipboard.writeText(text);notify('Copied your result to the clipboard!')}catch{notify('Sharing is unavailable on this browser.')}}}};}
function mount(){document.querySelector('#nav-home').onclick=goHome;window.addEventListener('popstate',()=>{screen=screenFromLocation();if(screen==='game'||screen==='result'){state=loadSave();if(!state)screen='home'}render()});if(screen==='game'||screen==='result'){state=loadSave();if(!state)screen='home';else if(screen==='game'&&state.gameStatus!=='playing')screen='result'}if(['expenses','review'].includes(screen)&&!restoreExpenseDraft()){if(screen==='review')screen='expenses';salary=500000;plan=initialPlan(salary);priorities=initialPriorities();saveExpenseDraft()}render();const saved=loadSave();if(screen==='home'&&saved?.gameStatus==='playing'&&!sessionStorage.getItem('salary-survival-seen-save')){modalSave=saved;sessionStorage.setItem('salary-survival-seen-save','1');render()}}
mount();
